// Simple test to verify threshold parsing logic
function parseAndValidateThresholds(thresholdStrings = []) {
  const errors = [];
  const thresholds = {};

  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds, errors };
  }

  for (const threshStr of thresholdStrings) {
    const parts = threshStr.split('=');
    if (parts.length !== 2) {
      errors.push(`Malformed threshold: "${threshStr}". Expected format: <metric>=<number>`);
      continue;
    }

    const metricId = parts[0].trim();
    const minStr = parts[1].trim();

    if (!metricId) {
      errors.push(`Empty metric ID in threshold: "${threshStr}"`);
      continue;
    }

    let minValue;
    try {
      minValue = Number.parseFloat(minStr);
      if (Number.isNaN(minValue)) {
        throw new Error('Not a number');
      }
    } catch {
      errors.push(`Invalid min value "${minStr}" in threshold "${threshStr}". Must be a number.`);
      continue;
    }

    if (minValue < 0 || minValue > 1) {
      errors.push(`Invalid min value ${minValue} in threshold "${threshStr}". Must be between 0 and 1.`);
      continue;
    }

    thresholds[metricId] = minValue;
  }

  return { thresholds, errors };
}

// Test cases
const tests = [
  { input: ['exact_match=0.8'], expected: { thresholds: { exact_match: 0.8 }, errors: [] } },
  { input: ['exact_match=0.8', 'toxicity=0.9'], expected: { thresholds: { exact_match: 0.8, toxicity: 0.9 }, errors: [] } },
  { input: ['exact_match'], expected: { thresholds: {}, errors: [`Malformed threshold: "exact_match". Expected format: <metric>=<number>`] } },
  { input: ['exact_match=1.5'], expected: { thresholds: {}, errors: [`Invalid min value 1.5 in threshold "exact_match=1.5". Must be between 0 and 1.`] } },
  { input: ['exact_match=abc'], expected: { thresholds: {}, errors: [`Invalid min value "abc" in threshold "exact_match=abc". Must be a number.`] } },
  { input: [], expected: { thresholds: {}, errors: [] } },
];

let passed = 0;
let failed = 0;

tests.forEach((test, idx) => {
  const result = parseAndValidateThresholds(test.input);
  const match = JSON.stringify(result) === JSON.stringify(test.expected);
  if (match) {
    console.log(`✓ Test ${idx + 1} passed`);
    passed++;
  } else {
    console.log(`✗ Test ${idx + 1} failed`);
    console.log(`  Input: ${JSON.stringify(test.input)}`);
    console.log(`  Expected: ${JSON.stringify(test.expected)}`);
    console.log(`  Got: ${JSON.stringify(result)}`);
    failed++;
  }
});

console.log(`\nTotal: ${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
EOF
